import numpy as np

def simulate_spread(initial_grid, max_steps=200):
    """
    Simulates the spread and mutation process on a grid.
    Uses a higher max_steps for potentially slow spread on larger grids.
    """
    current_grid = np.array(initial_grid, dtype=int)
    N = current_grid.shape[0]

    for step in range(max_steps):
        next_grid = np.copy(current_grid)
        changes_made = False

        flips = {} 

        # Check all 2x2 windows
        for r in range(N - 1):
            for c in range(N - 1):
                subgrid = current_grid[r:r+2, c:c+2]
                sum_val = np.sum(subgrid)

                # Rule 1: Growth (Sum = 3)
                if sum_val == 3:
                    sterile_coords = np.argwhere(subgrid == 0)
                    if len(sterile_coords) == 1:
                        dr, dc = sterile_coords[0]
                        gr, gc = r + dr, c + dc

                        if (gr, gc) not in flips:
                            flips[(gr, gc)] = None 
                        flips[(gr, gc)] = 1
                        changes_made = True

                # Rule 2: Mutation (Sum = 2)
                elif sum_val == 2:
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    for gr, gc in cells:
                        current_val = current_grid[gr, gc]
                        new_val = 1 - current_val 

                        if (gr, gc) not in flips:
                            flips[(gr, gc)] = None
                        flips[(gr, gc)] = new_val
                        changes_made = True

        # Apply all queued changes simultaneously
        if changes_made:
            for (r, c), new_val in flips.items():
                if new_val is not None:
                    next_grid[r, c] = new_val

        # Check for full infection
        if np.all(next_grid == 1):
            return next_grid, True

        # Check for stabilization
        if not changes_made:
            return next_grid, False

        current_grid = next_grid

    return current_grid, False # Reached max steps without full infection

